CREATE TABLE IF NOT EXISTS bid_notices (
    bid_seq BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    department_code VARCHAR(50),
    project_name VARCHAR(500) NOT NULL,
    order_client VARCHAR(300),
    design_amt NUMERIC(19, 2),
    bid_type VARCHAR(50),
    announce_date VARCHAR(8),
    pq_regist_date VARCHAR(12),
    pq_submit_date VARCHAR(12),
    order_method VARCHAR(50),
    bid_date VARCHAR(12),
    bid_sucess_yn VARCHAR(1),
    pq_decide_empno VARCHAR(50),
    pq_decide_date VARCHAR(8),
    super_decide_empno VARCHAR(50),
    participate_yn VARCHAR(1),

    created_at TIMESTAMP,
    created_id VARCHAR(100),
    last_changed_at TIMESTAMP,
    last_changed_id VARCHAR(100),
    business_type VARCHAR(50),
    bid_closing_date VARCHAR(12),
    process_tag VARCHAR(50),
    bid_method VARCHAR(50),
    bid_submission VARCHAR(12),
    field_of_work_code VARCHAR(50),
    scope_of_work_code VARCHAR(50),
    reason_of_absence_code VARCHAR(50),
    site_briefing_date VARCHAR(12),
    tp_submit_date VARCHAR(12),
    tp_pass_yn VARCHAR(1),
    prime_contractor VARCHAR(300),
    remark VARCHAR(2000),
    refmat_yn VARCHAR(1)
);

CREATE INDEX IF NOT EXISTS ix_bid_notices_project_name ON bid_notices (project_name);
CREATE INDEX IF NOT EXISTS ix_bid_notices_order_client ON bid_notices (order_client);
CREATE INDEX IF NOT EXISTS ix_bid_notices_bid_submission ON bid_notices (bid_submission);
CREATE INDEX IF NOT EXISTS ix_bid_notices_department_code ON bid_notices (department_code);
CREATE INDEX IF NOT EXISTS ix_bid_notices_bid_type ON bid_notices (bid_type);
CREATE INDEX IF NOT EXISTS ix_bid_notices_business_type ON bid_notices (business_type);
CREATE INDEX IF NOT EXISTS ix_bid_notices_field_scope ON bid_notices (field_of_work_code, scope_of_work_code);

COMMENT ON TABLE bid_notices IS '공고문 관리';
COMMENT ON COLUMN bid_notices.bid_seq IS '순번';
COMMENT ON COLUMN bid_notices.department_code IS '부서코드';
COMMENT ON COLUMN bid_notices.project_name IS '프로젝트 이름';
COMMENT ON COLUMN bid_notices.order_client IS '발주처';
COMMENT ON COLUMN bid_notices.design_amt IS '설계금액';
COMMENT ON COLUMN bid_notices.bid_type IS '입찰 구분';
COMMENT ON COLUMN bid_notices.announce_date IS '공고일';
COMMENT ON COLUMN bid_notices.pq_regist_date IS 'PQ등록일';
COMMENT ON COLUMN bid_notices.pq_submit_date IS 'PQ제출일';
COMMENT ON COLUMN bid_notices.order_method IS '발주 방법';
COMMENT ON COLUMN bid_notices.bid_sucess_yn IS '낙찰 여부';
COMMENT ON COLUMN bid_notices.bid_date IS '입찰 날짜';
COMMENT ON COLUMN bid_notices.pq_decide_empno IS NULL;
COMMENT ON COLUMN bid_notices.pq_decide_date IS NULL;
COMMENT ON COLUMN bid_notices.super_decide_empno IS '작성자';
COMMENT ON COLUMN bid_notices.participate_yn IS '참여여부';
COMMENT ON COLUMN bid_notices.created_at IS '입력날짜';
COMMENT ON COLUMN bid_notices.created_id IS '입력 담당자';
COMMENT ON COLUMN bid_notices.last_changed_at IS '최종 변경일';
COMMENT ON COLUMN bid_notices.last_changed_id IS '최종 변경자';
COMMENT ON COLUMN bid_notices.business_type IS '사업구분';
COMMENT ON COLUMN bid_notices.bid_closing_date IS '입찰등록 마감일';
COMMENT ON COLUMN bid_notices.process_tag IS NULL;
COMMENT ON COLUMN bid_notices.bid_method IS '입찰 방식';
COMMENT ON COLUMN bid_notices.bid_submission IS '투찰 마감일';
COMMENT ON COLUMN bid_notices.field_of_work_code IS '사업분야';
COMMENT ON COLUMN bid_notices.scope_of_work_code IS '사업범위';
COMMENT ON COLUMN bid_notices.reason_of_absence_code IS '불참사유 코드';
COMMENT ON COLUMN bid_notices.site_briefing_date IS '현장 설명회';
COMMENT ON COLUMN bid_notices.tp_submit_date IS 'TP제출일자';
COMMENT ON COLUMN bid_notices.tp_pass_yn IS NULL;
COMMENT ON COLUMN bid_notices.prime_contractor IS '대표업체';
COMMENT ON COLUMN bid_notices.remark IS '비고';
COMMENT ON COLUMN bid_notices.refmat_yn IS NULL;

